from collections import Counter, deque

def components(grid):
 h,w=len(grid),len(grid[0]); seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if (r,c) in seen: continue
   col=grid[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    a,b=q.pop();comp.append((a,b))
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     x,y=a+dr,b+dc
     if 0<=x<h and 0<=y<w and (x,y) not in seen and grid[x][y]==col:
      seen.add((x,y));q.append((x,y))
   comps.append((col,comp))
 return comps

def fill_neighbor(grid):
 out=[row[:] for row in grid]; h,w=len(grid),len(grid[0]); singles=[p for col,co in components(grid) if len(co)==1 for p in co]
 for r,c in singles:
  count=Counter(grid[rr][cc] for rr in range(max(0,r-1),min(h,r+2)) for cc in range(max(0,c-1),min(w,c+2)) if (rr,cc)!=(r,c))
  # if tie prefer cardinal direction count, then global count
  best=count.most_common()
  top=[x for x,n in best if n==best[0][1]]
  if len(top)>1:
   card=Counter(grid[rr][cc] for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=rr<h and 0<=cc<w and grid[rr][cc]!=grid[r][c])
   if card:
    m=max(card.values()); top2=[x for x,n in card.items() if n==m]
    if len(top2)==1: top=top2
  if len(top)>1:
   top=[max(top,key=lambda x:sum(1 for row in grid for v in row if v==x))]
  out[r][c]=top[0]
 return out
