def fill_with_bridge_rule(grid):
 h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]; bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
 comps=components(grid); compid={p:i for i,(color,co) in enumerate(comps) for p in co}; compcolor={i:color for i,(color,co) in enumerate(comps)}
 for col,co in comps:
  if len(co)!=1:continue
  r,c=co[0]; pos=[(r+dr,c+dc) for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)) if 0<=r+dr<h and 0<=c+dc<w]
  cnt=Counter(grid[x][y] for x,y in pos); m=max(cnt.values()); cand=[x for x,n in cnt.items() if n==m]
  if len(cand)>1:
   byc={x:{compid[p] for p in pos if grid[p[0]][p[1]]==x} for x in cand}
   # when a contender would bridge separate components, retain background on a tie
   if bg in cand and any(x!=bg and len(ids)>1 for x,ids in byc.items()): choice=bg
   else:
    fg=[x for x in cand if x!=bg]
    choice=fg[0] if len(fg)==1 else max(cand,key=lambda x:sum(row.count(x) for row in grid))
  else: choice=cand[0]
  out[r][c]=choice
 return out
